// The vectors are generated by the Python implementation (scripts/jws.py),
// so these tests check Go against an independent implementation.
func TestSignatureVectors(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "..", "testdata", "vectors", "signatures.json"))
	if err != nil {
		t.Fatal(err)
	}
	var file struct {
		Vectors []struct {
			Name, Alg, Kid, Typ, Payload, JWS, Seed string
			Valid                                   bool
			JWK                                     map[string]any
		}
	}
	if err := json.Unmarshal(raw, &file); err != nil {
		t.Fatal(err)
	}
	if len(file.Vectors) == 0 {
		t.Fatal("no signature vectors")
	}
	for _, v := range file.Vectors {
		t.Run(v.Name, func(t *testing.T) {
			key, err := parseJWK(v.JWK)
			if err != nil {
				t.Fatal(err)
			}
			err = Verify(v.JWS, []byte(v.Payload), key, v.Alg, v.Kid, v.Typ)
			if v.Valid && err != nil {
				t.Fatalf("rejected a valid signature: %v", err)
			}
			if !v.Valid && err == nil {
				t.Fatal("accepted an invalid signature")
			}
			if v.Seed == "" {
				return
			}
			// Ed25519 is deterministic: Go must produce the same bytes as Python.
			seed, err := hex.DecodeString(v.Seed)
			if err != nil {
				t.Fatal(err)
			}
			got, err := Sign(ed25519.NewKeyFromSeed(seed), v.Alg, v.Kid, v.Typ, []byte(v.Payload))
			if err != nil {
				t.Fatal(err)
			}
			if got != v.JWS {
				t.Fatalf("Go signed differently from Python:\ngot  %s\nwant %s", got, v.JWS)
			}
		})
	}
}

func TestES256RoundTrip(t *testing.T) {
	priv, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	payload := []byte(`{"a":1}`)
	jws, err := Sign(priv, ES256, "k", "a-witness-seal", payload)
	if err != nil {
		t.Fatal(err)
	}
	if err := Verify(jws, payload, &priv.PublicKey, ES256, "k", "a-witness-seal"); err != nil {
		t.Fatalf("own signature rejected: %v", err)
	}
	if err := Verify(jws, []byte(`{"a":2}`), &priv.PublicKey, ES256, "k", "a-witness-seal"); !errors.Is(err, ErrBadSignature) {
		t.Fatalf("changed payload: got %v, want ErrBadSignature", err)
	}
}

func TestSignRefusesMismatchedKey(t *testing.T) {
	_, edKey, _ := ed25519.GenerateKey(rand.Reader)
	if _, err := Sign(edKey, ES256, "k", "t", nil); err == nil {
		t.Fatal("signed ES256 with an Ed25519 key")
	}
	if _, err := Sign(edKey, "HS256", "k", "t", nil); err == nil {
		t.Fatal("signed with an unsupported algorithm")
	}
}

func TestJWKSRoundTripAndRefusals(t *testing.T) {
	edPub, _, _ := ed25519.GenerateKey(rand.Reader)
	ecPriv, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	var keys []any
	for kid, pub := range map[string]any{"ed": edPub, "ec": &ecPriv.PublicKey} {
		jwk, err := PublicJWK(pub, kid)
		if err != nil {
			t.Fatal(err)
		}
		keys = append(keys, jwk)
	}
	doc, _ := json.Marshal(map[string]any{"keys": keys})
	set, err := ParseJWKS(doc)
	if err != nil {
		t.Fatal(err)
	}
	if !edPub.Equal(set["ed"]) || !ecPriv.PublicKey.Equal(set["ec"]) {
		t.Fatal("keys did not survive a JWKS round trip")
	}

	for name, jwks := range map[string]string{
		"no kid":             `{"keys":[{"kty":"OKP","crv":"Ed25519","x":"11qYAYKxCrfVS_7TyWQHOg7hcvPapiMlrwIaaPcHURo"}]}`,
		"duplicate kid":      `{"keys":[{"kty":"OKP","crv":"Ed25519","kid":"a","x":"11qYAYKxCrfVS_7TyWQHOg7hcvPapiMlrwIaaPcHURo"},{"kty":"OKP","crv":"Ed25519","kid":"a","x":"11qYAYKxCrfVS_7TyWQHOg7hcvPapiMlrwIaaPcHURo"}]}`,
		"private key":        `{"keys":[{"kty":"OKP","crv":"Ed25519","kid":"a","x":"11qYAYKxCrfVS_7TyWQHOg7hcvPapiMlrwIaaPcHURo","d":"nWGxne_9WmC6hEr0kuwsxERJxWl7MmkZcDusAxyuf2A"}]}`,
		"short key":          `{"keys":[{"kty":"OKP","crv":"Ed25519","kid":"a","x":"AAAA"}]}`,
		"point not on curve": `{"keys":[{"kty":"EC","crv":"P-256","kid":"a","x":"AQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","y":"AQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"}]}`,
		"RSA":                `{"keys":[{"kty":"RSA","kid":"a","n":"AQAB","e":"AQAB"}]}`,
	} {
		if _, err := ParseJWKS([]byte(jwks)); err == nil {
			t.Errorf("%s: accepted", name)
		}
	}
}

func TestJWKSFetcher(t *testing.T) {
	pub, _, _ := ed25519.GenerateKey(rand.Reader)
	jwk, _ := PublicJWK(pub, "seal-2026")
	body, _ := json.Marshal(map[string]any{"keys": []any{jwk}})
	fetches := 0
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fetches++
		switch r.URL.Path {
		case "/jwks.json":
			w.Write(body)
		case "/huge.json":
			w.Write([]byte(`{"keys":[` + strings.Repeat(" ", maxJWKSBytes) + `]}`))
		default:
			http.NotFound(w, r)
		}
	}))
	defer srv.Close()
	f := &JWKSFetcher{Client: srv.Client()}
	ctx := context.Background()

	for range 2 {
		got, err := f.PublicKey(ctx, srv.URL+"/jwks.json#seal-2026")
		if err != nil {
			t.Fatal(err)
		}
		if !pub.Equal(got) {
			t.Fatal("fetched the wrong key")
		}
	}
	if fetches != 1 {
		t.Errorf("fetched %d times, want 1 (cached)", fetches)
	}

	for _, id := range []string{
		srv.URL + "/jwks.json#missing",
		srv.URL + "/gone.json#seal-2026",
		srv.URL + "/huge.json#seal-2026",
		strings.Replace(srv.URL, "https", "http", 1) + "/jwks.json#seal-2026", // plain HTTP refused
		srv.URL + "/jwks.json",                                                // no kid
	} {
		if _, err := f.PublicKey(ctx, id); err == nil {
			t.Errorf("%s: resolved", id)
		}
	}
	if _, err := f.PublicKey(ctx, srv.URL+"/jwks.json#missing"); !errors.Is(err, ErrUnknownKey) {
		t.Errorf("missing kid: got %v, want ErrUnknownKey", err)
	}
}

// jwksBody returns a JWKS holding one fresh Ed25519 key with the given kid.
func jwksBody(t *testing.T, kid string) ([]byte, ed25519.PublicKey) {
	t.Helper()
	pub, _, _ := ed25519.GenerateKey(rand.Reader)
	jwk, _ := PublicJWK(pub, kid)
	body, err := json.Marshal(map[string]any{"keys": []any{jwk}})
	if err != nil {
		t.Fatal(err)
	}
	return body, pub
}

func TestJWKSFetcherSlowHostDoesNotBlockOthers(t *testing.T) {
	slowBody, slowPub := jwksBody(t, "slow")
	fastBody, fastPub := jwksBody(t, "fast")
	entered := make(chan struct{})
	release := make(chan struct{})
	slow := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		close(entered)
		<-release
		w.Write(slowBody)
	}))
	defer slow.Close()
	defer func() {
		select {
		case <-release:
		default:
			close(release)
		}
	}()
	fast := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write(fastBody)
	}))
	defer fast.Close()

	pool := x509.NewCertPool()
	pool.AddCert(slow.Certificate())
	pool.AddCert(fast.Certificate())
	f := &JWKSFetcher{Client: &http.Client{Transport: &http.Transport{
		TLSClientConfig: &tls.Config{RootCAs: pool},
	}}}

	type result struct {
		key any
		err error
	}
	slowDone := make(chan result, 1)
	go func() {
		k, err := f.PublicKey(context.Background(), slow.URL+"/jwks.json#slow")
		slowDone <- result{k, err}
	}()
	select {
	case <-entered:
	case <-time.After(2 * time.Second):
		t.Fatal("slow handler was never entered")
	}

	fastDone := make(chan result, 1)
	go func() {
		k, err := f.PublicKey(context.Background(), fast.URL+"/jwks.json#fast")
		fastDone <- result{k, err}
	}()
	select {
	case r := <-fastDone:
		if r.err != nil {
			t.Fatalf("fast lookup: %v", r.err)
		}
		if !fastPub.Equal(r.key.(ed25519.PublicKey)) {
			t.Error("fast host: wrong key")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("fast lookup blocked behind the slow host")
	}
	select {
	case r := <-slowDone:
		t.Fatalf("slow lookup finished early: %+v", r)
	default:
	}

	close(release)
	select {
	case r := <-slowDone:
		if r.err != nil {
			t.Fatal(r.err)
		}
		if !slowPub.Equal(r.key.(ed25519.PublicKey)) {
			t.Error("slow host: wrong key")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("slow lookup did not finish after release")
	}
}

func TestJWKSFetcherConcurrentLookupsFetchOnce(t *testing.T) {
	const n = 10
	body, pub := jwksBody(t, "k1")
	var requests atomic.Int32
	var started sync.WaitGroup
	started.Add(n)
	allStarted := make(chan struct{})
	go func() { started.Wait(); close(allStarted) }()
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requests.Add(1)
		select {
		case <-allStarted:
		case <-time.After(5 * time.Second):
		}
		w.Write(body)
	}))
	defer srv.Close()
	f := &JWKSFetcher{Client: srv.Client()}

	var wg sync.WaitGroup
	errs := make(chan error, n)
	for range n {
		wg.Add(1)
		go func() {
			defer wg.Done()
			started.Done()
			got, err := f.PublicKey(context.Background(), srv.URL+"/jwks.json#k1")
			if err == nil && !pub.Equal(got) {
				err = errors.New("wrong key")
			}
			errs <- err
		}()
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		if err != nil {
			t.Error(err)
		}
	}
	if got := requests.Load(); got != 1 {
		t.Errorf("fetched %d times, want 1", got)
	}
}

func TestJWKSFetcherRetriesAfterFailure(t *testing.T) {
	body, pub := jwksBody(t, "k1")
	var requests atomic.Int32
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests.Add(1) == 1 {
			http.Error(w, "boom", http.StatusInternalServerError)
			return
		}
		w.Write(body)
	}))
	defer srv.Close()
	f := &JWKSFetcher{Client: srv.Client()}
	id := srv.URL + "/jwks.json#k1"

	if _, err := f.PublicKey(context.Background(), id); err == nil {
		t.Fatal("first lookup succeeded, want an error")
	}
	got, err := f.PublicKey(context.Background(), id)
	if err != nil {
		t.Fatalf("retry failed: %v", err)
	}
	if !pub.Equal(got) {
		t.Error("retry returned the wrong key")
	}
	if _, err := f.PublicKey(context.Background(), id); err != nil {
		t.Fatal(err)
	}
	if got := requests.Load(); got != 2 {
		t.Errorf("fetched %d times, want 2 (failure not cached, success cached)", got)
	}
}

// A caller whose ctx is live must not fail because the caller that started
// the fetch had its ctx cancelled.
func TestJWKSFetcherWaiterSurvivesFetcherCancel(t *testing.T) {
	body, pub := jwksBody(t, "k1")
	var requests atomic.Int32
	entered := make(chan struct{})
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if requests.Add(1) == 1 {
			close(entered)
			<-r.Context().Done() // the first caller gives up
			return
		}
		w.Write(body)
	}))
	defer srv.Close()
	f := &JWKSFetcher{Client: srv.Client()}
	id := srv.URL + "/jwks.json#k1"

	ctxA, cancelA := context.WithCancel(context.Background())
	defer cancelA()
	aDone := make(chan error, 1)
	go func() { _, err := f.PublicKey(ctxA, id); aDone <- err }()
	select {
	case <-entered:
	case <-time.After(2 * time.Second):
		t.Fatal("first fetch never started")
	}

	type result struct {
		key any
		err error
	}
	bDone := make(chan result, 1)
	go func() {
		k, err := f.PublicKey(context.Background(), id)
		bDone <- result{k, err}
	}()
	time.Sleep(50 * time.Millisecond) // let B join A's fetch
	cancelA()

	select {
	case r := <-bDone:
		if r.err != nil {
			t.Fatalf("B failed because A's ctx ended: %v", r.err)
		}
		if !pub.Equal(r.key.(ed25519.PublicKey)) {
			t.Error("B got the wrong key")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("B did not finish")
	}
	if err := <-aDone; err == nil {
		t.Error("A succeeded, want its ctx error")
	}
}

func TestJWKSFetcherWaiterCancelReturnsPromptly(t *testing.T) {
	body, _ := jwksBody(t, "k1")
	entered := make(chan struct{})
	release := make(chan struct{})
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		close(entered)
		<-release
		w.Write(body)
	}))
	defer srv.Close()
	defer func() {
		select {
		case <-release:
		default:
			close(release)
		}
	}()
	f := &JWKSFetcher{Client: srv.Client()}
	id := srv.URL + "/jwks.json#k1"

	leaderDone := make(chan error, 1)
	go func() { _, err := f.PublicKey(context.Background(), id); leaderDone <- err }()
	select {
	case <-entered:
	case <-time.After(2 * time.Second):
		t.Fatal("fetch never started")
	}

	ctx, cancel := context.WithCancel(context.Background())
	waiterDone := make(chan error, 1)
	go func() { _, err := f.PublicKey(ctx, id); waiterDone <- err }()
	time.Sleep(50 * time.Millisecond)
	cancel()
	select {
	case err := <-waiterDone:
		if !errors.Is(err, context.Canceled) {
			t.Errorf("waiter: got %v, want context.Canceled", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("waiter did not return after its ctx was cancelled")
	}

	close(release)
	select {
	case err := <-leaderDone:
		if err != nil {
			t.Errorf("leader: %v", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("leader did not finish")
	}
}

func TestJWKSFetcherCachedLookupIgnoresCancelledCtx(t *testing.T) {
	body, pub := jwksBody(t, "k1")
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write(body)
	}))
	defer srv.Close()
	f := &JWKSFetcher{Client: srv.Client()}
	id := srv.URL + "/jwks.json#k1"
	if _, err := f.PublicKey(context.Background(), id); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	for i := range 200 {
		got, err := f.PublicKey(ctx, id)
		if err != nil {
			t.Fatalf("lookup %d of a cached key with a cancelled ctx: %v", i, err)
		}
		if !pub.Equal(got) {
			t.Fatal("wrong key")
		}
	}
}

func ExampleSign() {
	key := ed25519.NewKeyFromSeed(make([]byte, 32)) // never use a fixed key outside an example
	payload := []byte(`{"mandate_id":"mdt_exampleExample"}`)
	jws, _ := Sign(key, EdDSA, "https://keys.example/jwks.json#k1", "a-witness-mandate", payload)
	fmt.Println(Verify(jws, payload, key.Public(), EdDSA, "https://keys.example/jwks.json#k1", "a-witness-mandate"))
	// Output: <nil>
}
